Definition PUT_DISP    : Z := 0x39660.
Definition PUT_LOOPCHK : Z := 0x39890.
Definition PUT_COMMON  : Z := 0x397f8.
Definition PUT_RET     : Z := 0x3991c.
Definition PUT_EPI     : Z := 0x39924.
Definition PUT_NM      : Z := 0x39960.
Definition PUT_JT      : Z := 0x14f0c.
Definition PUT_FRAME   : Z := 144.

Definition put_targets : list Z :=
  [0x39674; 0x3967c; 0x396b8; 0x3974c; 0x3978c; 0x397a4; 0x397e4; 0x39814; 0x39854; 0x396f8; 0x398c0; 0x39910].
Definition put_target (st : Z) : Z := nth (Z.to_nat st) put_targets 0.
Definition PUT_JT_CELLS : list cell := map (fun t => C4 (wz (t - PUT_JT))) put_targets.

Definition put_sv (s11 s10 s9 s8 s7 s6 s5 s4 s3 s2 s1 s0 ra : word) : list word := [s11; s10; s9; s8; s7; s6; s5; s4; s3; s2; s1; s0; ra].

Lemma ro_cells_reshape : forall segs m A cs cs',
  ro_cells segs m A cs -> cells_wf cs' -> cells_bytes cs' = cells_bytes cs -> ro_cells segs m A cs'.
Proof. intros segs m A cs cs' [WF B] WF' E. split; [exact WF'| rewrite E; exact B]. Qed.

(* [comment removed for export] *)
Local Ltac blob2 H1 H2 :=
  let j1 := fresh "jb" in let j2 := fresh "jb" in let B1 := fresh "BL" in let B2 := fresh "BL" in
  destruct (rw_cells_forget _ _ _ _ H1) as [j1 B1]; destruct (rw_cells_forget _ _ _ _ H2) as [j2 B2]; clear H1 H2;
  cbn [cells_size csize Nat.add map] in B1, B2;
  lazymatch type of B1 with rw_cells _ _ ?a1 [CB ?n1 _] =>
    lazymatch type of B2 with rw_cells _ _ ?a2 _ =>
      replace a2 with (a1 + Z.of_nat n1) in B2 by lia;
      pose proof (rw_cells_CB_join rsegs _ _ _ _ _ _ B1 B2) as H1; clear B1 B2; cbn [Nat.add] in H1
    end end.

Section HCW.
