(* [comment removed for export] *)
Lemma put_jt : forall m, mem_inv rsegs m -> ro_cells rsegs m PUT_JT PUT_JT_CELLS.
Proof.
  intros m MI.
  assert (L : length (cells_bytes PUT_JT_CELLS) = 48%nat) by (vm_compute; reflexivity).
  pose proof (ro_cells_image rsegs m PUT_JT (cells_bytes PUT_JT_CELLS) MI
    ltac:(vm_compute; reflexivity) ltac:(unfold PUT_JT; lia) ltac:(rewrite L; unfold PUT_JT; lia)) as R.
  apply (ro_cells_reshape _ _ _ _ _ R); vm_compute; [tauto | reflexivity].
Qed.

