Definition put_frame (m : mem) (sp : word) (j8 : list byte) (tmp : list cell) (p : Z) : Prop :=
  rw_cells rsegs m (bv_unsigned sp + -144) [CB 8 j8]
  /\ rw_cells rsegs m (bv_unsigned sp + -136) tmp /\ cells_size tmp = 24%nat
  /\ rw_cells rsegs m (bv_unsigned sp + -112) [C8 (wz p)].
