    (F : bvmap 5 word) fc (m : mem) (lo : Z) (j8 : list byte) (tmp : list cell) (p k : Z),
  put_frame m sp j8 tmp p ->
  rw_cells rsegs m (bv_unsigned sp + -104) (map C8 (put_sv s11v s10v s9v s8v s7v s6v s5v s4v s3v s2v s1v s0v ra)) ->
  stk rsegs m lo (bv_unsigned sp + -144) -> 0 <= lo -> lo <= bv_unsigned sp + -144 ->
  evt rsegs (put_retd_post ra sp gp tp s0v s1v s2v s3v s4v s5v s6v s7v s8v s9v s10v s11v F fc lo k m)
    (MS (mkR rax (Z_to_bv 64 (bv_unsigned sp + -144)) gp tp t0 t1 t2 s0x s1x (wz k) a1 a2 a3 a4 a5 a6 a7
              s2x s3x s4x s5x s6x s7x s8x s9x s10x s11x t3 t4 t5 t6)
