(* [comment removed for export] *)
Definition put_entry_stmt : Prop :=
  forall ra sp gp tp t0 t1 t2 s0 s1 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6
    (F : bvmap 5 word) fc (m : mem) (lo P E : Z) (c : pcore) (pad7 pad2 ej : list byte) (p0 n : Z),
  rw_cells rsegs m P (ParserCoreCells c pad7 pad2) -> pcore_ok c -> pc_state c <> 11 ->
  rw_cells rsegs m E [CB 24 ej] ->
  stk rsegs m lo (bv_unsigned sp) -> lo + 144 <= bv_unsigned sp -> 0xb4000 <= lo ->
  bv_unsigned sp <= P -> P + 80 <= 2^64 -> bv_unsigned sp <= E -> E + 24 <= 2^64 -> (P + 80 <= E \/ E + 24 <= P) ->
  0 <= p0 -> 0 <= n -> p0 + n < 2^64 ->
  mem_inv rsegs m ->
  evt rsegs (fun ms' => exists a1 m' j8 jt,
        ms' = MS (mkR ra (Z_to_bv 64 (bv_unsigned sp + -144)) gp tp t0 t1 t2 (wz E) (wz p0) (wz (pc_state c)) a1 (wz p0) (wz E) a4 a5 a6 a7
                      (wz P) (wz n) (wz 11) (wz (p0 + n)) (wz 1) (wz PUT_JT) (wz 4) (wz 6) (wz 8) (wz 10) t3 t4 t5 t6)
                 F (Z_to_bv 64 PUT_DISP) fc None m' (seg_rom rsegs)
        /\ munch [(lo, bv_unsigned sp); (E, E + 24)]%Z m m' /\ wmono rsegs m m' /\ mem_inv rsegs m'
        /\ stk rsegs m' lo (bv_unsigned sp + -144)
